'use client';

import { useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ChevronLeft, ChevronRight, Filter } from 'lucide-react';
import { JournalLedgerEntry, TransactionCursor, TransactionFilters } from '../models/finance.model';
import { TransactionTraceDrawer } from './TransactionTraceDrawer';

interface TransactionsTableProps {
  initialData: JournalLedgerEntry[];
  nextCursor?: TransactionCursor;
  filters: TransactionFilters;
}

export function TransactionsTable({ initialData, nextCursor, filters }: TransactionsTableProps) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [selectedTxnId, setSelectedTxnId] = useState<string | null>(null);

  const handleNextPage = () => {
    if (!nextCursor) return;
    const params = new URLSearchParams(searchParams.toString());
    params.set('cursor_created_at', nextCursor.created_at);
    params.set('cursor_id', nextCursor.journal_id);
    router.push(`?${params.toString()}`);
  };

  const handleClearFilters = () => {
    router.push('/dashboard/finance/transactions');
  };

  return (
    <div className="space-y-4">
      {/* Basic Filter Info Bar */}
      <div className="flex items-center justify-between p-4 border-b">
        <div className="flex items-center gap-2">
          <h3 className="text-lg font-semibold">Ledger Transactions</h3>
          {(filters.event_type || filters.status) && (
            <Badge variant="secondary" className="ml-2">
              <Filter className="h-3 w-3 mr-1" /> Filters Active
            </Badge>
          )}
        </div>
        <div className="flex gap-2">
          {(filters.event_type || filters.status) && (
            <Button variant="ghost" size="sm" onClick={handleClearFilters}>
              Clear Filters
            </Button>
          )}
        </div>
      </div>

      <div className="overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Journal ID</TableHead>
              <TableHead>Event Type</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Payer / Payee</TableHead>
              <TableHead className="text-right">Gross</TableHead>
              <TableHead className="text-right">Fee</TableHead>
              <TableHead className="text-right">Net</TableHead>
              <TableHead>Date</TableHead>
              <TableHead></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {initialData.length > 0 ? (
              initialData.map((txn) => (
                <TableRow key={txn.journal_id} className="hover:bg-muted/50 cursor-pointer" onClick={() => setSelectedTxnId(txn.journal_id)}>
                  <TableCell className="font-mono text-xs">{txn.journal_id.slice(0, 8)}...</TableCell>
                  <TableCell>
                    <Badge variant="outline">{txn.event_type}</Badge>
                  </TableCell>
                  <TableCell>
                    <Badge 
                      variant="secondary"
                      className={
                        txn.status === 'posted' ? 'bg-green-500/10 text-green-500' : 'bg-orange-500/10 text-orange-500'
                      }
                    >
                      {txn.status}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-xs">
                    <div><span className="text-muted-foreground mr-1">Fr:</span> {txn.payer_user_id ? txn.payer_user_id.slice(0, 8) + '...' : 'System'}</div>
                    <div><span className="text-muted-foreground mr-1">To:</span> {txn.payee_user_id ? txn.payee_user_id.slice(0, 8) + '...' : 'System'}</div>
                  </TableCell>
                  <TableCell className="text-right font-mono">{txn.gross_amount}</TableCell>
                  <TableCell className="text-right font-mono text-destructive">{txn.fee_amount > 0 ? `-${txn.fee_amount}` : '0'}</TableCell>
                  <TableCell className="text-right font-mono font-medium">{txn.net_amount}</TableCell>
                  <TableCell className="text-muted-foreground text-sm">
                    {new Date(txn.created_at).toLocaleString()}
                  </TableCell>
                  <TableCell className="text-right">
                    <Button variant="ghost" size="sm" onClick={(e) => { e.stopPropagation(); setSelectedTxnId(txn.journal_id); }}>
                      Details
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={9} className="h-24 text-center text-muted-foreground">
                  No transactions found.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <div className="flex items-center justify-end space-x-2 py-4 px-4 border-t">
        <Button
          variant="outline"
          size="sm"
          onClick={() => router.back()}
          disabled={!searchParams.get('cursor_id')}
        >
          <ChevronLeft className="h-4 w-4 mr-1" /> Previous
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={handleNextPage}
          disabled={!nextCursor}
        >
          Next <ChevronRight className="h-4 w-4 ml-1" />
        </Button>
      </div>

      {selectedTxnId && (
        <TransactionTraceDrawer 
          journalId={selectedTxnId} 
          open={!!selectedTxnId} 
          onOpenChange={(open: boolean) => !open && setSelectedTxnId(null)} 
        />
      )}
    </div>
  );
}
